// Generated by /ship test audit (Claude Opus 5.5) — 2026-10-18
// Value: protects=an SB settlement period whose server row reports unconfigured SB orders says "n chưa cấu hình" in its Xác nhận cell, so its operating-cost sum is not read as complete; a period without any keeps the plain split;
// fails_when=SettlementRow drops or inverts the unconfiguredCount > 0 branch, or reads the count from another field (the period's cost total then hides the orders it leaves out);
// why_new=every settlement row rendered by finance-orders-page.test.tsx and the preview fixtures has unconfiguredCount 0, so the warning branch never renders;
// seam=none (the server settlement row is a fixture; next/navigation and the finance actions module are mocked as in finance-orders-page.test.tsx); no_claim=that the RPC counts unconfigured SB orders correctly (SQL, not exercised here)
import { cleanup, render, screen, within } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";

import { FinanceOrdersPage } from "@/features/finance/components/finance-orders-page";
import type { FinanceOrderReadModel, FinanceOrdersDashboardReadModel } from "@/features/finance/read-models";

vi.mock("next/navigation", () => ({
  useRouter: () => ({ replace: vi.fn() }),
  useSearchParams: () => new URLSearchParams("month=2026-08"),
}));
vi.mock("@/features/finance/actions/finance-actions", () => ({ setFinanceOrderReviewAction: vi.fn() }));

afterEach(cleanup);

const sbOrder = (id: string, overrides: Partial<FinanceOrderReadModel>): FinanceOrderReadModel => ({
  bankTransactionId: `SEPAY-${id}`,
  checkedAt: null,
  checkedBy: null,
  classCode: "7A",
  className: "Toán 7A",
  guardianFullName: "Nguyễn Thị Mai",
  guardianPhone: "0900000000",
  isChecked: false,
  leadSourceCode: "sandbox_partner",
  leadSourceName: "Đối tác Sandbox",
  mechanismCode: "renewal_sb_20_percent",
  operatingCostStatus: "configured",
  operatingCostVnd: 560_000,
  orderType: "renewal",
  referenceCode: `PAY-${id}`,
  saleOwnerFullName: "Trần Hải",
  saleOwnerId: "sale-1",
  sepayTransactionId: `transaction-${id}`,
  settlementPeriod: 1,
  sourceCashflowRecordId: `cashflow-${id}`,
  sourceCode: "sb",
  sourceLabel: "SB",
  studentFullName: `Học sinh ${id}`,
  studentId: `student-${id}`,
  studentPublicCode: `HV${id}`,
  transactionAt: "2026-08-05T03:00:00.000Z",
  transferContent: `TTVC PAY-${id}`,
  tuitionAmountVnd: 2_800_000,
  ...overrides,
});

// Period 1: one configured SB renewal. Period 2: an SB order of unknown purpose has no
// cost policy (unconfigured), so the server cost sum covers only the configured one.
const orders = [
  sbOrder("1", { isChecked: true }),
  sbOrder("2", { settlementPeriod: 2, transactionAt: "2026-08-12T03:00:00.000Z" }),
  sbOrder("3", {
    mechanismCode: "unconfigured",
    operatingCostStatus: "unconfigured",
    operatingCostVnd: null,
    orderType: "unknown",
    settlementPeriod: 2,
    transactionAt: "2026-08-13T03:00:00.000Z",
  }),
];

const dashboard: FinanceOrdersDashboardReadModel = {
  month: "2026-08-01",
  orders,
  settlement: [
    { checkedCount: 1, newEnrollmentCount: 0, operatingCostVnd: 560_000, period: 1, renewalCount: 1, tuitionAmountVnd: 2_800_000, uncheckedCount: 0, unconfiguredCount: 0 },
    { checkedCount: 0, newEnrollmentCount: 0, operatingCostVnd: 560_000, period: 2, renewalCount: 1, tuitionAmountVnd: 5_600_000, uncheckedCount: 2, unconfiguredCount: 1 },
  ],
  settlementEligible: true,
  summary: { checkedCount: 1, operatingCostVnd: 1_120_000, orderCount: 3, tuitionAmountVnd: 8_400_000, uncheckedCount: 2, unconfiguredCount: 1 },
};

describe("Finance Orders SB settlement (step 14c)", () => {
  it("names the unconfigured SB orders a period's cost sum leaves out, and only there", () => {
    render(
      <FinanceOrdersPage
        canReview={false}
        dashboard={dashboard}
        filters={{ month: "2026-08", orderType: "", period: "", source: "" }}
        today="2026-10-16"
      />,
    );

    const rows = within(screen.getByRole("table", { name: "Quyết toán chi phí vận hành SB theo đợt" }))
      .getAllByRole("row")
      .slice(1);
    const reviewCell = (row: HTMLElement) => within(row).getAllByRole("cell").at(-1)!;

    expect(rows).toHaveLength(3);
    expect(reviewCell(rows[0]!)).toHaveTextContent(/^1 đã · 0 chưa$/);
    expect(reviewCell(rows[1]!)).toHaveTextContent(/^0 đã · 2 chưa · 1 chưa cấu hình$/);
    expect(within(reviewCell(rows[1]!)).getByText("· 1 chưa cấu hình")).toHaveClass("text-warning");
    expect(reviewCell(rows[2]!)).toHaveTextContent(/^0 đã · 0 chưa$/);
  });

  it("marks the running period of the current month and leaves later periods as not started, not zero", () => {
    render(
      <FinanceOrdersPage
        canReview={false}
        dashboard={dashboard}
        filters={{ month: "2026-08", orderType: "", period: "", source: "" }}
        today="2026-08-15"
      />,
    );

    const rows = within(screen.getByRole("table", { name: "Quyết toán chi phí vận hành SB theo đợt" }))
      .getAllByRole("row")
      .slice(1);
    const cells = (row: HTMLElement) => within(row).getAllByRole("cell");

    expect(within(cells(rows[0]!)[0]!).queryByText(/đang diễn ra|chưa tới/)).not.toBeInTheDocument();
    expect(within(cells(rows[1]!)[0]!).getByText("đang diễn ra (đến hôm nay)")).toBeInTheDocument();
    expect(cells(rows[1]!).at(-1)).toHaveTextContent(/^0 đã · 2 chưa · 1 chưa cấu hình$/);
    expect(within(cells(rows[2]!)[0]!).getByText("chưa tới")).toBeInTheDocument();
    expect(cells(rows[2]!).slice(1).map((cell) => cell.textContent)).toEqual(["—", "—", "—", "—", "—"]);
  });

  it("marks every period of a future month as not started", () => {
    render(
      <FinanceOrdersPage
        canReview={false}
        dashboard={dashboard}
        filters={{ month: "2026-08", orderType: "", period: "", source: "" }}
        today="2026-07-30"
      />,
    );

    const rows = within(screen.getByRole("table", { name: "Quyết toán chi phí vận hành SB theo đợt" }))
      .getAllByRole("row")
      .slice(1);
    expect(rows.map((row) => within(row).getByText("chưa tới"))).toHaveLength(3);
    expect(screen.queryByText("đang diễn ra (đến hôm nay)")).not.toBeInTheDocument();
  });

  it("shows — for a period whose SB orders all lack a cost policy, and the real sum when one has it", () => {
    const unknownOnly = sbOrder("9", {
      mechanismCode: "unconfigured",
      operatingCostStatus: "unconfigured",
      operatingCostVnd: null,
      orderType: "unknown",
      settlementPeriod: 1,
    });
    render(
      <FinanceOrdersPage
        canReview={false}
        dashboard={{
          ...dashboard,
          orders: [unknownOnly, ...orders.slice(1)],
          settlement: [
            { checkedCount: 0, newEnrollmentCount: 0, operatingCostVnd: 0, period: 1, renewalCount: 0, tuitionAmountVnd: 2_800_000, uncheckedCount: 1, unconfiguredCount: 1 },
            dashboard.settlement[1]!,
          ],
        }}
        filters={{ month: "2026-08", orderType: "", period: "", source: "" }}
        today="2026-10-16"
      />,
    );

    const rows = within(screen.getByRole("table", { name: "Quyết toán chi phí vận hành SB theo đợt" }))
      .getAllByRole("row")
      .slice(1);
    const costCell = (row: HTMLElement) => within(row).getAllByRole("cell")[4]!;
    expect(costCell(rows[0]!)).toHaveTextContent(/^—$/);
    // Period 2 mixes a configured and an unconfigured order: the configured one counts.
    expect(costCell(rows[1]!)).toHaveTextContent("560.000 ₫");
    // Period 3 is a finished period with no SB order: a real zero.
    expect(costCell(rows[2]!)).toHaveTextContent(/^0\s₫$/);
  });

  // Columns: 0 Đợt · 1 Tuyển mới · 2 Tái phí.
  it.each([
    ["renewal", 2, 1],
    ["new_enrollment", 1, 2],
  ] as const)("scopes the settlement to a Loại đơn filter (%s): the left-out type is —, not 0", (orderType, shownColumn, hiddenColumn) => {
    render(
      <FinanceOrdersPage
        canReview={false}
        dashboard={dashboard}
        filters={{ month: "2026-08", orderType, period: "", source: "" }}
        today="2026-10-16"
      />,
    );

    expect(screen.getByText("Chỉ tính đơn nguồn SB · theo bộ lọc · Đợt 1: 01–10 · Đợt 2: 11–20 · Đợt 3: 21–cuối tháng.")).toBeInTheDocument();
    const rows = within(screen.getByRole("table", { name: "Quyết toán chi phí vận hành SB theo đợt" }))
      .getAllByRole("row")
      .slice(1);
    for (const row of rows) {
      const cells = within(row).getAllByRole("cell");
      expect(cells[hiddenColumn]).toHaveTextContent(/^—$/);
      expect(cells[shownColumn]).toHaveTextContent(/^\d+$/);
    }
  });

  it("keeps the unscoped intro and both type columns without a Loại đơn filter", () => {
    render(
      <FinanceOrdersPage
        canReview={false}
        dashboard={dashboard}
        filters={{ month: "2026-08", orderType: "", period: "", source: "sb" }}
        today="2026-10-16"
      />,
    );

    expect(screen.getByText("Chỉ tính đơn nguồn SB · Đợt 1: 01–10 · Đợt 2: 11–20 · Đợt 3: 21–cuối tháng.")).toBeInTheDocument();
    const first = within(within(screen.getByRole("table", { name: "Quyết toán chi phí vận hành SB theo đợt" })).getAllByRole("row")[1]!).getAllByRole("cell");
    expect(first[1]).toHaveTextContent(/^0$/);
    expect(first[2]).toHaveTextContent(/^1$/);
  });
});
